import { useEffect, useMemo, useState } from "react"
import { createPortal } from "react-dom"
import {
  HiChevronRight,
  HiChevronLeft,
  HiOutlineArchiveBox,
  HiOutlineCheckCircle,
  HiOutlineEye,
  HiOutlineMagnifyingGlass,
  HiOutlinePlus,
  HiOutlinePrinter,
  HiOutlineArrowPath,
  HiOutlineXMark,
} from "react-icons/hi2"
import { FiChevronUp, FiMoreVertical } from "react-icons/fi"

import cardBackArtwork from "../../../../../assets/images/discount-card-back.png"
import cardFrontArtwork from "../../../../../assets/images/discount-card-front.png"
import managerIdBackArtwork from "../../../../../assets/images/manager-id-back.png"
import managerIdFrontArtwork from "../../../../../assets/images/manager-id-front.png"

const moneyRule = {
  id: "rule-pwd-senior",
  name: "PWD & Senior Citizen Discount",
  eligibility: ["PWD", "Senior Citizen"],
  value: 20,
  applicability: "Eligible items/products only",
  branches: "All applicable branches",
  reverifyMonths: "24",
  status: "Active",
}

const initialCards = [
  { id: "card-1", cardId: "LYFE-0001", barcode: "LYFE-0001", name: "Juan Dela Cruz", type: "PWD", governmentId: "PWD-1234-5678", issued: "Aug 26, 2026", issuedShort: "08/26/26", reverifyBy: "Aug 26, 2028", reverifyShort: "08/26/28", status: "Active" },
]

const fixedBranches = ["Camalig", "Guinobatan", "Polangui", "Daraga", "Manito"]

const inputClass = "h-11 w-full rounded-lg border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-900 outline-none focus:border-[#0b6b51]"

function SuperAdminDiscounts({ users = [] }) {
  const rule = moneyRule
  const managers = useMemo(() => users.map((user, index) => ({ ...user, employeeId: user.employeeId ?? `EMP-${String(index + 1).padStart(4, "0")}` })).filter((user) => ["Branch Admin", "Branch Manager"].includes(user.role) && user.status === "Active"), [users])
  const [activeSection, setActiveSection] = useState("discount-cards")
  const [cards, setCards] = useState(initialCards)
  const [managerIds, setManagerIds] = useState(() => managers[0] ? [{ ...managers[0], id: `manager-id-${managers[0].id}`, barcode: managers[0].employeeId, photo: "", idStatus: "Active" }] : [])
  const [query, setQuery] = useState("")
  const [statusFilter, setStatusFilter] = useState("All Statuses")
  const [managerQuery, setManagerQuery] = useState("")
  const [branchFilter, setBranchFilter] = useState("All Branches")
  const [modal, setModal] = useState(null)
  const [page, setPage] = useState(1)
  const [rowsPerPage, setRowsPerPage] = useState(10)
  const [selectedIds, setSelectedIds] = useState([])
  const [actionMenu, setActionMenu] = useState(null)
  const [successMessage, setSuccessMessage] = useState("")

  const filteredCards = useMemo(() => {
    const term = query.trim().toLowerCase()
    return cards.map((card) => ({ ...card, status: resolveCardStatus(card) })).filter((card) => {
      const matchesQuery = !term || [card.name, card.cardId, card.barcode].some((value) => value.toLowerCase().includes(term))
      return matchesQuery && (statusFilter === "All Statuses" || card.status === statusFilter)
    })
  }, [cards, query, statusFilter])
  const pageCount = Math.max(1, Math.ceil(filteredCards.length / rowsPerPage))
  const currentPage = Math.min(page, pageCount)
  const visibleCards = filteredCards.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage)
  const paginationItems = getPaginationItems(currentPage, pageCount)
  const selectedCards = cards.map((card) => ({ ...card, status: resolveCardStatus(card) })).filter((card) => selectedIds.includes(card.cardId))
  const visibleIds = visibleCards.map((card) => card.cardId)
  const selectedVisibleCount = visibleIds.filter((id) => selectedIds.includes(id)).length
  const allVisibleSelected = visibleIds.length > 0 && selectedVisibleCount === visibleIds.length
  const someVisibleSelected = selectedVisibleCount > 0 && !allVisibleSelected
  const allSelectedActive = selectedCards.length > 0 && selectedCards.every((card) => card.status === "Active")

  useEffect(() => {
    if (!actionMenu) return undefined
    const closeMenu = () => setActionMenu(null)
    const closeOnEscape = (event) => { if (event.key === "Escape") closeMenu() }
    window.addEventListener("mousedown", closeMenu)
    window.addEventListener("keydown", closeOnEscape)
    window.addEventListener("resize", closeMenu)
    window.addEventListener("scroll", closeMenu, true)
    return () => { window.removeEventListener("mousedown", closeMenu); window.removeEventListener("keydown", closeOnEscape); window.removeEventListener("resize", closeMenu); window.removeEventListener("scroll", closeMenu, true) }
  }, [actionMenu])

  useEffect(() => {
    if (!successMessage) return undefined
    const timer = window.setTimeout(() => setSuccessMessage(""), 4000)
    return () => window.clearTimeout(timer)
  }, [successMessage])

  const toggleActionMenu = (event, card) => { event.stopPropagation(); if (actionMenu?.card.cardId === card.cardId) return setActionMenu(null); const rect = event.currentTarget.getBoundingClientRect(); const opensUp = rect.bottom + 168 > window.innerHeight - 12; setActionMenu({ card, right: Math.max(12, window.innerWidth - rect.right), top: opensUp ? undefined : rect.bottom + 6, bottom: opensUp ? window.innerHeight - rect.top + 6 : undefined }) }
  const toggleCardSelection = (cardId) => setSelectedIds((current) => current.includes(cardId) ? current.filter((id) => id !== cardId) : [...current, cardId])
  const toggleVisibleSelection = () => setSelectedIds((current) => allVisibleSelected ? current.filter((id) => !visibleIds.includes(id)) : [...new Set([...current, ...visibleIds])])

  const nextCardId = `LYFE-${String(cards.length + 1).padStart(4, "0")}`
  const branches = fixedBranches
  const eligibleManagers = managers.filter((manager) => manager.branch && !managerIds.some((id) => id.employeeId === manager.employeeId && id.idStatus === "Active"))
  const syncedManagerIds = managerIds.map((record) => { const user = managers.find((manager) => manager.employeeId === record.employeeId); return user ? { ...record, ...user, photo: record.photo || user.photo || "", barcode: record.barcode, idStatus: record.idStatus } : record })
  const visibleManagerIds = syncedManagerIds.filter((manager) => {
    const term = managerQuery.trim().toLowerCase()
    return (!term || [manager.name, manager.employeeId].some((value) => value.toLowerCase().includes(term))) && (branchFilter === "All Branches" || manager.branch === branchFilter)
  })

  const issueCard = (draft) => {
    const card = { ...draft, id: `card-${Date.now()}`, status: "Active" }
    setCards((current) => [...current, card])
    setModal({ type: "preview-existing", card })
  }

  const updateCard = (cardId, updates) => {
    setCards((current) => current.map((card) => card.cardId === cardId ? { ...card, ...updates } : card))
    setModal((current) => current?.card?.cardId === cardId ? { ...current, card: { ...current.card, ...updates } } : current)
  }

  const deactivateSelectedCards = () => {
    const selectedSet = new Set(selectedIds)
    setCards((current) => current.map((card) => selectedSet.has(card.cardId) ? { ...card, status: "Inactive" } : card))
    setSelectedIds([])
    setModal(null)
  }

  const issueManagerId = (manager) => {
    const managerRecord = { ...manager, id: `manager-id-${Date.now()}`, idStatus: "Active" }
    setManagerIds((current) => [...current, managerRecord])
    setModal(null)
    setSuccessMessage(`${manager.name}'s Manager ID was generated successfully.`)
  }

  return (
    <div className="mx-auto w-full max-w-[1600px] px-4 pb-6 sm:px-6 lg:px-8">
      <h1 className="text-xl font-bold text-slate-950 lg:hidden">Card Management</h1>
      <nav className="mb-4 mt-2 flex border-b border-slate-200 lg:mb-5 lg:mt-0" aria-label="Card management sections">
        {[["discount-cards", "Discount Cards"], ["manager-ids", "Manager IDs"]].map(([id, label]) => <button key={id} type="button" onClick={() => setActiveSection(id)} className={`h-11 border-b-2 px-3 text-sm font-bold lg:h-12 lg:px-4 ${activeSection === id ? "border-[#0b6b51] text-[#0b6b51]" : "border-transparent text-slate-500 hover:text-slate-900"}`}>{label}</button>)}
      </nav>

      {activeSection === "discount-cards" ? <>
      <section className="rounded-xl border border-slate-200 bg-white p-4 shadow-[0_8px_24px_rgba(15,23,42,0.05)] sm:p-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <h2 className="text-base font-bold text-slate-950">PWD &amp; Senior Citizen Discount</h2>
          <StatusBadge status={rule.status} />
        </div>
        <div className="mt-3 grid grid-cols-2 gap-x-4 gap-y-3 border-t border-slate-100 pt-3 lg:mt-4 lg:grid-cols-5 lg:gap-y-4 lg:divide-x lg:divide-slate-100 lg:pt-4">
          <div className="col-span-2 lg:col-span-1"><PolicyValue label="Discount Rate" value={`${rule.value}% Discount`} primary /></div>
          <PolicyValue label="Eligible Customers" value="PWD & Senior Citizen" />
          <div className="col-span-2 lg:col-span-1"><PolicyValue label="Eligible Items" value="PWD/Senior eligible products" /></div>
          <PolicyValue label="Re-verification" value="2 Years" />
          <PolicyValue label="Applies To" value="All Branches" />
        </div>
      </section>

      <section className="mt-4 overflow-hidden rounded-xl border border-transparent bg-transparent shadow-none lg:mt-6 lg:border-slate-200 lg:bg-white lg:shadow-[0_8px_24px_rgba(15,23,42,0.05)]">
          <div className="lg:p-5">
            <div className="mb-3 flex items-center justify-between gap-3 lg:hidden"><h2 className="text-lg font-bold text-slate-950">Discount Cards <span className="text-slate-500">({filteredCards.length})</span></h2><button type="button" onClick={() => setModal({ type: "generate" })} className="inline-flex h-10 shrink-0 items-center gap-1.5 rounded-lg bg-[#00675b] px-3 text-xs font-bold text-white"><HiOutlinePlus className="h-4 w-4" />Generate</button></div>
            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
              <div className="flex flex-col gap-2.5 sm:flex-row sm:items-center lg:gap-3"><SearchField value={query} onChange={(value) => { setQuery(value); setPage(1); setSelectedIds([]) }} placeholder="Search cardholder or Card ID..." noMargin /><select value={statusFilter} onChange={(event) => { setStatusFilter(event.target.value); setPage(1); setSelectedIds([]) }} className={`${inputClass} sm:w-48`}><option>All Statuses</option><option>Active</option><option>Re-verification Due</option><option>Inactive</option></select></div>
              <button type="button" onClick={() => setModal({ type: "generate" })} className="hidden h-11 items-center justify-center gap-2 self-start rounded-lg bg-[#00675b] px-5 text-sm font-bold text-white hover:bg-[#005348] lg:inline-flex lg:self-auto"><HiOutlinePlus className="h-5 w-5" />Generate Card</button>
            </div>
            {selectedCards.length ? <div className="mt-4 flex flex-col gap-3 rounded-xl border border-emerald-200 bg-emerald-50/60 px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex flex-wrap items-center gap-3"><p className="text-sm font-bold text-[#0b6b51]">{selectedCards.length} card{selectedCards.length === 1 ? "" : "s"} selected</p><button type="button" onClick={() => setSelectedIds([])} className="text-xs font-bold text-slate-500 underline-offset-2 hover:text-slate-800 hover:underline">Clear Selection</button></div>{selectedCards.length >= 2 ? <span className="inline-flex" title={allSelectedActive ? "Deactivate selected cards" : "Deactivate Cards is available only when all selected cards are Active."}><button type="button" disabled={!allSelectedActive} onClick={() => setModal({ type: "bulk-deactivate" })} className="h-10 rounded-lg bg-red-600 px-4 text-sm font-bold text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-400">Deactivate Cards</button></span> : null}</div> : null}
            <div className="mt-3 space-y-2.5 lg:hidden">{visibleCards.length ? visibleCards.map((card) => <article key={card.cardId} className="relative rounded-xl border border-slate-200 bg-white p-3.5 shadow-sm"><label className="absolute left-2 top-2 grid h-9 w-9 cursor-pointer place-items-center" aria-label={`Select ${card.cardId}`}><input type="checkbox" checked={selectedIds.includes(card.cardId)} onChange={() => toggleCardSelection(card.cardId)} className="h-4 w-4 cursor-pointer rounded border-slate-300 accent-[#00675b]" /></label><button type="button" onClick={() => setModal({ type: "card-details", card })} className="w-full px-8 text-left"><span className="flex items-start justify-between gap-3"><span className="font-bold text-[#0b6b51]">{card.cardId}</span><StatusBadge status={card.status} /></span><span className="mt-2 block whitespace-normal break-words text-sm font-bold text-slate-950">{card.name}</span><span className="mt-1 flex items-center justify-between text-xs font-semibold text-slate-500"><span>{card.type}</span><HiChevronRight className="h-5 w-5 text-slate-400" /></span></button><button type="button" onClick={(event) => toggleActionMenu(event, card)} className="absolute right-2 top-2 grid h-9 w-9 place-items-center rounded-full text-slate-700 hover:bg-slate-100" aria-label={`Actions for ${card.cardId}`}><FiMoreVertical className="h-5 w-5" /></button></article>) : <div className="rounded-xl border border-slate-200 bg-white px-4 py-6 text-center"><p className="text-sm font-bold text-slate-600">{cards.length ? "No matching discount cards" : "No discount cards"}</p><p className="mt-1 text-xs text-slate-400">{cards.length ? "Try adjusting your search or status filter." : "Generated cards will appear here."}</p></div>}</div>
            <div className="mt-4 hidden overflow-hidden rounded-xl border border-slate-200 lg:block"><div className="overflow-x-auto"><table className="w-full min-w-[960px] text-left text-sm"><thead className="bg-slate-50 text-xs font-bold uppercase text-slate-500"><tr><th className="w-12 px-4 py-3 text-center"><input ref={(checkbox) => { if (checkbox) checkbox.indeterminate = someVisibleSelected }} type="checkbox" checked={allVisibleSelected} disabled={!visibleCards.length} onChange={toggleVisibleSelection} className="h-4 w-4 cursor-pointer rounded border-slate-300 accent-[#00675b]" aria-label="Select all cards on this page" /></th><th className="px-4 py-3">Card ID</th><th className="px-4 py-3">Cardholder</th><th className="px-4 py-3">Type</th><th className="px-4 py-3">Date Issued</th><th className="px-4 py-3">Re-verify By</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-center">Action</th></tr></thead><tbody>{visibleCards.length ? visibleCards.map((card) => <tr key={card.cardId} className="border-t border-slate-100"><td className="px-4 py-3 text-center"><input type="checkbox" checked={selectedIds.includes(card.cardId)} onChange={() => toggleCardSelection(card.cardId)} className="h-4 w-4 cursor-pointer rounded border-slate-300 accent-[#00675b]" aria-label={`Select ${card.cardId}`} /></td><td className="px-4 py-3 font-bold text-[#0b6b51]">{card.cardId}</td><td className="px-4 py-3 font-bold text-slate-900">{card.name}</td><td className="px-4 py-3 text-slate-600">{card.type}</td><td className="px-4 py-3 text-slate-600">{card.issued}</td><td className="px-4 py-3 text-slate-600">{card.reverifyBy}</td><td className="px-4 py-3"><StatusBadge status={card.status} /></td><td className="px-4 py-3"><button type="button" onClick={(event) => toggleActionMenu(event, card)} className="mx-auto grid h-9 w-9 place-items-center rounded-full text-slate-700 hover:bg-slate-100" aria-label={`Actions for ${card.cardId}`}><FiMoreVertical className="h-5 w-5" /></button></td></tr>) : <EmptyRow colSpan={8} title="No discount cards generated yet." detail="Generated PWD and Senior Citizen cards will appear here." />}</tbody></table></div><CardsPagination currentPage={currentPage} filteredCount={filteredCards.length} pageCount={pageCount} paginationItems={paginationItems} rowsPerPage={rowsPerPage} setPage={setPage} setRowsPerPage={setRowsPerPage} onPageSizeChange={() => setSelectedIds([])} /></div>
            <div className="mt-3 overflow-hidden rounded-xl border border-slate-200 bg-white lg:hidden"><CardsPagination currentPage={currentPage} filteredCount={filteredCards.length} pageCount={pageCount} paginationItems={paginationItems} rowsPerPage={rowsPerPage} setPage={setPage} setRowsPerPage={setRowsPerPage} onPageSizeChange={() => setSelectedIds([])} /></div>
          </div>
      </section>
      </> : <ManagerIdsPanel managerIds={visibleManagerIds} branches={branches} query={managerQuery} setQuery={setManagerQuery} branchFilter={branchFilter} setBranchFilter={setBranchFilter} onGenerate={() => setModal({ type: "generate-manager" })} onView={(manager) => setModal({ type: "manager-details", manager })} onReprint={(manager) => setModal({ type: "manager-preview", manager })} onDeactivate={(manager) => setModal({ type: "deactivate-manager", manager })} />}

      {actionMenu ? <DiscountCardActionMenu menu={actionMenu} onView={(card) => { setActionMenu(null); setModal({ type: "card-details", card }) }} onReprint={(card) => { setActionMenu(null); setModal({ type: "preview-existing", card }) }} onReverify={(card) => { setActionMenu(null); setModal({ type: "reverify", card }) }} onDeactivate={(card) => { setActionMenu(null); setModal({ type: "deactivate", card }) }} /> : null}
      {modal?.type === "generate" ? <GenerateCard nextCardId={nextCardId} reverifyMonths={rule.reverifyMonths} onClose={() => setModal(null)} onPreview={(card) => setModal({ type: "preview-new", card })} /> : null}
      {modal?.type === "preview-new" ? <CardPreview card={modal.card} onBack={() => setModal({ type: "generate" })} onPrimary={() => issueCard(modal.card)} primaryLabel="Generate & Print" printAfterPrimary /> : null}
      {modal?.type === "preview-existing" ? <CardPreview card={modal.card} onBack={() => setModal({ type: "card-details", card: modal.card })} onPrimary={() => window.print()} primaryLabel="Print Card" /> : null}
      {modal?.type === "card-details" ? <CardDetails card={modal.card} onClose={() => setModal(null)} onPreview={() => setModal({ type: "preview-existing", card: modal.card })} /> : null}
      {modal?.type === "reverify" ? <ReverifyCardModal card={modal.card} months={rule.reverifyMonths} onCancel={() => setModal(null)} onConfirm={(updates) => { const cardName = modal.card.name; updateCard(modal.card.cardId, updates); setModal(null); setSuccessMessage(`${cardName}'s discount card was re-verified successfully.`) }} /> : null}
      {modal?.type === "deactivate" ? <ConfirmDeactivate card={modal.card} onCancel={() => setModal(null)} onConfirm={() => { updateCard(modal.card.cardId, { status: "Inactive" }); setModal(null) }} /> : null}
      {modal?.type === "bulk-deactivate" ? <ConfirmBulkDeactivate count={selectedCards.length} onCancel={() => setModal(null)} onConfirm={deactivateSelectedCards} /> : null}
      {modal?.type === "generate-manager" ? <GenerateManagerId managers={eligibleManagers} onClose={() => setModal(null)} onPreview={(manager) => setModal({ type: "manager-preview-new", manager })} /> : null}
      {modal?.type === "manager-preview-new" ? <ManagerIdPreview manager={modal.manager} onClose={() => setModal({ type: "generate-manager" })} primaryLabel="Generate ID" onPrimary={() => issueManagerId(modal.manager)} generating /> : null}
      {modal?.type === "manager-details" ? <ManagerIdDetails manager={modal.manager} onClose={() => setModal(null)} /> : null}
      {modal?.type === "manager-preview" ? <ManagerIdPreview manager={modal.manager} onClose={() => setModal({ type: "manager-details", manager: modal.manager })} primaryLabel="Print ID" onPrimary={() => window.print()} /> : null}
      {modal?.type === "deactivate-manager" ? <ConfirmDeactivateManager manager={modal.manager} onCancel={() => setModal(null)} onConfirm={() => { setManagerIds((current) => current.map((item) => item.employeeId === modal.manager.employeeId ? { ...item, idStatus: "Inactive" } : item)); setModal(null) }} /> : null}
      {successMessage ? <div role="status" aria-live="polite" className="fixed bottom-5 right-5 z-[120] flex w-[calc(100%-2rem)] max-w-sm items-start gap-3 rounded-xl border border-emerald-200 bg-white p-4 shadow-xl"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-emerald-100 text-emerald-700"><HiOutlineCheckCircle className="h-6 w-6" /></span><div className="min-w-0 flex-1"><p className="font-bold text-slate-950">{successMessage.includes("Manager ID") ? "Manager ID Generated" : "Re-verification Complete"}</p><p className="mt-1 text-sm text-slate-600">{successMessage}</p></div><button type="button" onClick={() => setSuccessMessage("")} className="grid h-8 w-8 shrink-0 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700" aria-label="Dismiss notification"><HiOutlineXMark className="h-5 w-5" /></button></div> : null}
    </div>
  )
}

function ManagerIdsPanel({ branchFilter, branches, managerIds, onDeactivate, onGenerate, onReprint, onView, query, setBranchFilter, setQuery }) {
  const [page, setPage] = useState(1)
  const [rowsPerPage, setRowsPerPage] = useState(10)
  const [menu, setMenu] = useState(null)
  const [selectedIds, setSelectedIds] = useState([])
  const pageCount = Math.max(1, Math.ceil(managerIds.length / rowsPerPage))
  const currentPage = Math.min(page, pageCount)
  const visibleManagers = managerIds.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage)
  const visibleIds = visibleManagers.map((manager) => manager.employeeId)
  const selectedVisibleCount = visibleIds.filter((id) => selectedIds.includes(id)).length
  const allVisibleSelected = visibleIds.length > 0 && selectedVisibleCount === visibleIds.length
  const someVisibleSelected = selectedVisibleCount > 0 && !allVisibleSelected
  const paginationItems = getPaginationItems(currentPage, pageCount)
  useEffect(() => {
    if (!menu) return undefined
    const close = () => setMenu(null)
    window.addEventListener("mousedown", close)
    window.addEventListener("scroll", close, true)
    window.addEventListener("resize", close)
    return () => { window.removeEventListener("mousedown", close); window.removeEventListener("scroll", close, true); window.removeEventListener("resize", close) }
  }, [menu])
  const openMenu = (event, manager) => { event.stopPropagation(); const rect = event.currentTarget.getBoundingClientRect(); setMenu({ manager, right: Math.max(12, window.innerWidth - rect.right), top: rect.bottom + 6 }) }
  const changeSearch = (value) => { setQuery(value); setPage(1); setMenu(null); setSelectedIds([]) }
  const changeBranch = (value) => { setBranchFilter(value); setPage(1); setMenu(null); setSelectedIds([]) }
  const toggleManager = (employeeId) => setSelectedIds((current) => current.includes(employeeId) ? current.filter((id) => id !== employeeId) : [...current, employeeId])
  const toggleVisible = () => setSelectedIds((current) => allVisibleSelected ? current.filter((id) => !visibleIds.includes(id)) : [...new Set([...current, ...visibleIds])])
  return <section className="overflow-hidden rounded-xl border border-transparent bg-transparent shadow-none lg:border-slate-200 lg:bg-white lg:shadow-[0_8px_24px_rgba(15,23,42,0.05)]"><div className="lg:p-5"><div className="mb-3 flex items-center justify-between gap-3 lg:hidden"><h2 className="text-lg font-bold text-slate-950">Manager IDs <span className="text-slate-500">({managerIds.length})</span></h2><button type="button" onClick={onGenerate} className="inline-flex h-10 shrink-0 items-center gap-1.5 rounded-lg bg-[#00675b] px-3 text-xs font-bold text-white"><HiOutlinePlus className="h-4 w-4" />Generate ID</button></div><div className="flex flex-col gap-2.5 lg:flex-row lg:items-center lg:justify-between lg:gap-3"><div className="flex flex-col gap-2.5 sm:flex-row sm:items-center lg:gap-3"><SearchField value={query} onChange={changeSearch} placeholder="Search manager or Employee ID..." noMargin /><select value={branchFilter} onChange={(event) => changeBranch(event.target.value)} className={`${inputClass} sm:w-52`}><option>All Branches</option>{branches.map((branch) => <option key={branch}>{branch}</option>)}</select></div><button type="button" onClick={onGenerate} className="hidden h-11 items-center justify-center gap-2 rounded-lg bg-[#00675b] px-5 text-sm font-bold text-white hover:bg-[#005348] lg:inline-flex"><HiOutlinePlus className="h-5 w-5" />Generate Manager ID</button></div><div className="mt-3 space-y-2.5 lg:hidden">{visibleManagers.length ? visibleManagers.map((manager) => <article key={manager.id} className="relative rounded-xl border border-slate-200 bg-white p-3.5 shadow-sm"><button type="button" onClick={() => onView(manager)} className="w-full pr-10 text-left"><span className="flex items-start justify-between gap-3"><span className="font-bold text-[#0b6b51]">{manager.employeeId}</span><StatusBadge status={manager.idStatus} /></span><span className="mt-2 block text-sm font-bold text-slate-950">{manager.name}</span><span className="mt-1 block text-xs text-slate-500">{manager.role} · {manager.branch}</span></button><button type="button" onClick={(event) => openMenu(event, manager)} className="absolute right-2 top-2 grid h-9 w-9 place-items-center rounded-full text-slate-700 hover:bg-slate-100" aria-label={`Actions for ${manager.name}`}><FiMoreVertical className="h-5 w-5" /></button></article>) : <div className="rounded-xl border border-slate-200 bg-white px-4 py-6 text-center"><p className="text-sm font-bold text-slate-600">No Manager IDs found</p><p className="mt-1 text-xs text-slate-400">Try adjusting the search or branch filter.</p></div>}</div><div className="mt-4 hidden overflow-hidden rounded-xl border border-slate-200 lg:block"><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-slate-50 text-xs font-bold uppercase text-slate-500"><tr><th className="w-12 px-4 py-3 text-center"><input ref={(checkbox) => { if (checkbox) checkbox.indeterminate = someVisibleSelected }} type="checkbox" checked={allVisibleSelected} disabled={!visibleManagers.length} onChange={toggleVisible} className="h-4 w-4 cursor-pointer rounded border-slate-300 accent-[#00675b]" aria-label="Select all Manager IDs on this page" /></th><th className="px-4 py-3">Employee ID</th><th className="px-4 py-3">Manager</th><th className="px-4 py-3">Branch</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-center">Action</th></tr></thead><tbody>{visibleManagers.length ? visibleManagers.map((manager) => <tr key={manager.id} className="border-t border-slate-100"><td className="px-4 py-3 text-center"><input type="checkbox" checked={selectedIds.includes(manager.employeeId)} onChange={() => toggleManager(manager.employeeId)} className="h-4 w-4 cursor-pointer rounded border-slate-300 accent-[#00675b]" aria-label={`Select ${manager.name}`} /></td><td className="px-4 py-3 font-bold text-[#0b6b51]">{manager.employeeId}</td><td className="px-4 py-3"><p className="font-bold text-slate-900">{manager.name}</p><p className="mt-0.5 text-xs text-slate-500">{manager.role}</p></td><td className="px-4 py-3 text-slate-600">{manager.branch}</td><td className="px-4 py-3"><StatusBadge status={manager.idStatus} /></td><td className="px-4 py-3"><button type="button" onClick={(event) => openMenu(event, manager)} className="mx-auto grid h-9 w-9 place-items-center rounded-full text-slate-700 hover:bg-slate-100" aria-label={`Actions for ${manager.name}`}><FiMoreVertical className="h-5 w-5" /></button></td></tr>) : <EmptyRow colSpan={6} title="No manager IDs found." detail="Generate an ID for an eligible Branch Admin." />}</tbody></table></div><ManagerIdsPagination currentPage={currentPage} count={managerIds.length} pageCount={pageCount} paginationItems={paginationItems} rowsPerPage={rowsPerPage} setPage={setPage} setRowsPerPage={setRowsPerPage} /></div></div>{menu ? <ManagerIdActionMenu menu={menu} onClose={() => setMenu(null)} onView={onView} onReprint={onReprint} onDeactivate={onDeactivate} /> : null}</section>
}

function ManagerIdActionMenu({ menu, onClose, onDeactivate, onReprint, onView }) { const act = (callback) => { onClose(); callback(menu.manager) }; return <div role="menu" onMouseDown={(event) => event.stopPropagation()} className="fixed z-[110] w-48 rounded-xl border border-slate-200 bg-white p-1.5 shadow-[0_14px_35px_rgba(15,23,42,0.14)]" style={{ right: menu.right, top: menu.top }}><CardMenuAction icon={HiOutlineEye} label="Overview" onClick={() => act(onView)} /><CardMenuAction icon={HiOutlinePrinter} label="Reprint ID" onClick={() => act(onReprint)} />{menu.manager.idStatus === "Active" ? <div className="mt-1 border-t border-slate-100 pt-1"><CardMenuAction danger icon={HiOutlineArchiveBox} label="Deactivate ID" onClick={() => act(onDeactivate)} /></div> : null}</div> }

function ManagerIdsPagination({ count, currentPage, pageCount, paginationItems, rowsPerPage, setPage, setRowsPerPage }) { const showing = count ? `Showing ${(currentPage - 1) * rowsPerPage + 1}–${Math.min(currentPage * rowsPerPage, count)} of ${count} Manager IDs` : "Showing 0 of 0 Manager IDs"; return <div className="flex min-h-14 flex-col gap-3 border-t border-slate-100 px-4 py-3 text-sm font-semibold text-slate-500 sm:flex-row sm:items-center sm:justify-between"><p>{showing}</p><div className="flex items-center gap-3"><label className="relative block min-w-[10.75rem]"><select value={rowsPerPage} onChange={(event) => { setRowsPerPage(Number(event.target.value)); setPage(1) }} className="h-11 w-full appearance-none rounded-xl border border-slate-200 bg-white px-4 pr-10 text-base font-semibold text-slate-700 outline-none focus:border-[#0b6b51]"><option value="10">10 entries</option><option value="25">25 entries</option><option value="50">50 entries</option></select><FiChevronUp className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" /></label><nav className="flex items-center gap-2" aria-label="Manager IDs pagination"><PageButton disabled={currentPage === 1 || !count} onClick={() => setPage(currentPage - 1)}><HiChevronLeft className="h-5 w-5" /></PageButton>{count > rowsPerPage ? paginationItems.map((item, index) => item === "ellipsis" ? <span key={`manager-ellipsis-${index}`}>…</span> : <PageButton key={item} active={item === currentPage} onClick={() => setPage(item)}>{item}</PageButton>) : null}<PageButton disabled={currentPage === pageCount || !count} onClick={() => setPage(currentPage + 1)}><HiChevronRight className="h-5 w-5" /></PageButton></nav></div></div> }

function LegacyManagerIdsPanel({ branchFilter, branches, managerIds, onGenerate, onView, query, setBranchFilter, setQuery }) {
  return <section className="overflow-hidden rounded-xl border border-transparent bg-transparent shadow-none lg:border-slate-200 lg:bg-white lg:shadow-[0_8px_24px_rgba(15,23,42,0.05)]"><div className="lg:p-5"><div className="mb-3 flex items-center justify-between gap-3 lg:hidden"><h2 className="text-lg font-bold text-slate-950">Manager IDs <span className="text-slate-500">({managerIds.length})</span></h2><button type="button" onClick={onGenerate} className="inline-flex h-10 shrink-0 items-center gap-1.5 rounded-lg bg-[#00675b] px-3 text-xs font-bold text-white"><HiOutlinePlus className="h-4 w-4" />Generate ID</button></div><div className="flex flex-col gap-2.5 lg:flex-row lg:items-center lg:justify-between lg:gap-3"><div className="flex flex-col gap-2.5 sm:flex-row sm:items-center lg:gap-3"><SearchField value={query} onChange={setQuery} placeholder="Search manager or Employee ID..." noMargin /><select value={branchFilter} onChange={(event) => setBranchFilter(event.target.value)} className={`${inputClass} sm:w-52`}><option>All Branches</option>{branches.map((branch) => <option key={branch}>{branch}</option>)}</select></div><button type="button" onClick={onGenerate} className="hidden h-11 items-center justify-center gap-2 self-start rounded-lg bg-[#00675b] px-5 text-sm font-bold text-white hover:bg-[#005348] lg:inline-flex lg:self-auto"><HiOutlinePlus className="h-5 w-5" />Generate Manager ID</button></div><div className="mt-3 space-y-2.5 lg:hidden">{managerIds.length ? managerIds.map((manager) => <button key={manager.id} type="button" onClick={() => onView(manager)} className="w-full rounded-xl border border-slate-200 bg-white p-3.5 text-left shadow-sm"><span className="flex items-start justify-between gap-3"><span className="font-bold text-[#0b6b51]">{manager.employeeId}</span><StatusBadge status={manager.idStatus} /></span><span className="mt-2 block whitespace-normal break-words text-sm font-bold text-slate-950">{manager.name}</span><span className="mt-1 block text-xs text-slate-500">{manager.role} · {manager.branch}</span><span className="mt-3 flex items-center justify-between border-t border-slate-100 pt-2.5 text-xs"><span><span className="block font-medium text-slate-400">Manager ID</span><span className="mt-0.5 block font-bold text-slate-700">{manager.employeeId}</span></span><HiChevronRight className="h-5 w-5 text-slate-400" /></span></button>) : <div className="rounded-xl border border-slate-200 bg-white px-4 py-6 text-center"><p className="text-sm font-bold text-slate-600">No Manager IDs</p><p className="mt-1 text-xs font-medium text-slate-400">Generated Manager IDs will appear here.</p></div>}</div><div className="mt-4 hidden overflow-x-auto rounded-xl border border-slate-200 lg:block"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-slate-50 text-xs font-bold uppercase text-slate-500"><tr><th className="px-4 py-3">Employee ID</th><th className="px-4 py-3">Manager</th><th className="px-4 py-3">Branch</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-center">Action</th></tr></thead><tbody>{managerIds.length ? managerIds.map((manager) => <tr key={manager.id} className="border-t border-slate-100"><td className="px-4 py-3 font-bold text-[#0b6b51]">{manager.employeeId}</td><td className="px-4 py-3 font-bold text-slate-900">{manager.name}</td><td className="px-4 py-3 text-slate-600">{manager.branch}</td><td className="px-4 py-3"><StatusBadge status={manager.idStatus} /></td><td className="px-4 py-3"><ViewButton label="View Manager ID" onClick={() => onView(manager)} /></td></tr>) : <EmptyRow colSpan={5} title="No manager IDs found." detail="Generate an ID for an eligible Branch Manager." />}</tbody></table></div></div></section>
}

void LegacyManagerIdsPanel

function DiscountCardActionMenu({ menu, onDeactivate, onReprint, onReverify, onView }) {
  const active = menu.card.status === "Active"
  return <div role="menu" aria-label={`Actions for ${menu.card.cardId}`} onMouseDown={(event) => event.stopPropagation()} className="fixed z-[110] w-52 overflow-hidden rounded-xl border border-slate-200 bg-white p-1.5 shadow-[0_14px_35px_rgba(15,23,42,0.14)]" style={{ right: menu.right, top: menu.top, bottom: menu.bottom }}><CardMenuAction icon={HiOutlineEye} label="View Details" onClick={() => onView(menu.card)} /><CardMenuAction icon={HiOutlinePrinter} label="Reprint Card" onClick={() => onReprint(menu.card)} />{active || menu.card.status === "Re-verification Due" ? <CardMenuAction icon={HiOutlineArrowPath} label="Re-verify Card" onClick={() => onReverify(menu.card)} /> : null}{active ? <div className="mt-1 border-t border-slate-100 pt-1"><CardMenuAction danger icon={HiOutlineArchiveBox} label="Deactivate Card" onClick={() => onDeactivate(menu.card)} /></div> : null}</div>
}
function CardMenuAction({ danger = false, icon: Icon, label, onClick }) { return <button type="button" role="menuitem" onClick={onClick} className={`flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm font-semibold transition ${danger ? "text-red-600 hover:bg-red-50" : "text-slate-700 hover:bg-slate-50 hover:text-[#0b6b51]"}`}><Icon className="h-4 w-4 shrink-0" />{label}</button> }

function CardsPagination({ currentPage, filteredCount, onPageSizeChange, pageCount, paginationItems, rowsPerPage, setPage, setRowsPerPage }) { const showing = filteredCount ? `Showing ${(currentPage - 1) * rowsPerPage + 1}–${Math.min(currentPage * rowsPerPage, filteredCount)} of ${filteredCount} cards` : "Showing 0 of 0 cards"; return <div className="flex min-h-14 flex-col gap-3 border-t border-slate-100 bg-white px-4 py-3 text-sm font-semibold text-slate-500 sm:flex-row sm:items-center sm:justify-between lg:px-5"><p>{showing}</p><div className="flex flex-wrap items-center gap-3"><label className="relative block min-w-[10.75rem]"><select value={rowsPerPage} onChange={(event) => { setRowsPerPage(Number(event.target.value)); setPage(1); onPageSizeChange() }} className="h-11 w-full appearance-none rounded-xl border border-slate-200 bg-white px-4 pr-10 text-base font-semibold text-slate-700 outline-none focus:border-[#0b6b51]">{[10, 25, 50].map((amount) => <option key={amount} value={amount}>{amount} entries</option>)}</select><FiChevronUp className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" /></label><nav className="flex items-center gap-2" aria-label="Discount cards pagination"><PageButton disabled={currentPage === 1 || !filteredCount} onClick={() => setPage(Math.max(1, currentPage - 1))}><HiChevronLeft className="h-5 w-5" /></PageButton>{filteredCount > 0 && paginationItems.map((item, index) => item === "ellipsis" ? <span key={`ellipsis-${index}`} className="grid h-9 w-9 place-items-center">...</span> : <PageButton key={item} active={item === currentPage} onClick={() => setPage(item)}>{item}</PageButton>)}<PageButton disabled={currentPage === pageCount || !filteredCount} onClick={() => setPage(Math.min(pageCount, currentPage + 1))}><HiChevronRight className="h-5 w-5" /></PageButton></nav></div></div> }

function GenerateManagerId({ managers, onClose, onPreview }) {
  const [employeeId, setEmployeeId] = useState("")
  const [photo, setPhoto] = useState("")
  const [photoError, setPhotoError] = useState("")
  const manager = managers.find((item) => item.employeeId === employeeId)
  const handlePhoto = (event) => { const file = event.target.files?.[0]; if (!file) return; if (!["image/jpeg", "image/png"].includes(file.type)) { setPhoto(""); setPhotoError("Upload a valid JPG or PNG image."); return } const reader = new FileReader(); reader.onload = () => { setPhoto(String(reader.result)); setPhotoError("") }; reader.readAsDataURL(file) }
  const canPreview = Boolean(manager?.employeeId && manager?.name && manager?.branch && photo)
  return <Modal title="Generate Manager ID" onClose={onClose} maxWidth="max-w-2xl"><form onSubmit={(event) => { event.preventDefault(); if (canPreview) onPreview({ ...manager, photo, barcode: manager.employeeId, idStatus: "Active" }) }}><h3 className="text-xs font-bold uppercase tracking-wide text-slate-500">Manager Information</h3><div className="mt-3"><Field label="Select Manager *"><select required value={employeeId} onChange={(event) => { setEmployeeId(event.target.value); const selected = managers.find((item) => item.employeeId === event.target.value); setPhoto(selected?.photo || "") }} className={inputClass}><option value="">Select an eligible manager</option>{managers.map((item) => <option key={item.employeeId} value={item.employeeId}>{item.name} — {item.employeeId}</option>)}</select></Field>{!managers.length ? <p className="mt-2 text-sm text-amber-700">No eligible active Branch Admin users are available. Assign a branch or deactivate an existing Manager ID first.</p> : null}</div><div className="mt-4 grid gap-x-8 gap-y-3 sm:grid-cols-2"><ReadOnlyValue label="Full Name" value={manager?.name || "Not selected"} /><ReadOnlyValue label="Employee ID" value={manager?.employeeId || "Not selected"} /><ReadOnlyValue label="Role" value={manager?.role || "Not selected"} /><ReadOnlyValue label="Assigned Branch" value={manager?.branch || "Not selected"} /></div><h3 className="mt-4 border-t border-slate-100 pt-4 text-xs font-bold uppercase tracking-wide text-slate-500">Manager Photo *</h3><div className="mt-3 flex flex-wrap items-center gap-4"><div className="grid h-24 w-24 place-items-center overflow-hidden rounded-full border border-slate-200 bg-slate-50">{photo ? <img src={photo} alt="Manager preview" className="h-full w-full object-cover object-center" /> : <span className="text-xs font-bold text-slate-400">PHOTO</span>}</div><div><label className="inline-flex cursor-pointer rounded-lg border border-[#0b6b51]/30 px-4 py-2.5 text-sm font-bold text-[#0b6b51] hover:bg-emerald-50">{photo ? "Change Photo" : "Upload Photo"}<input type="file" accept="image/jpeg,image/png" onChange={handlePhoto} className="sr-only" /></label><p className={`mt-1.5 text-xs font-medium ${photoError ? "text-red-600" : "text-slate-400"}`}>{photoError || "JPG, JPEG or PNG"}</p></div></div><div className="mt-5 flex justify-end border-t border-slate-100 pt-4"><button type="submit" disabled={!canPreview} className="h-11 rounded-lg bg-[#00675b] px-6 text-sm font-bold text-white hover:bg-[#005348] disabled:cursor-not-allowed disabled:bg-slate-300">Preview ID</button></div></form></Modal>
}

function ManagerIdDetails({ manager, onClose }) {
  return <Modal title="Manager ID Details" onClose={onClose} maxWidth="max-w-4xl"><div className="flex items-start justify-between gap-4 border-b border-slate-100 pb-4"><div><h3 className="text-xl font-bold text-slate-950">{manager.employeeId}</h3><p className="mt-1 font-bold text-slate-800">{manager.name}</p><p className="mt-1 text-sm text-slate-500">{manager.role} <span className="px-1 text-slate-300">•</span> {manager.branch}</p></div><StatusBadge status={manager.idStatus} /></div><div className="grid gap-6 lg:grid-cols-[minmax(0,58fr)_minmax(320px,42fr)] lg:gap-0"><div className="min-w-0 lg:pr-5"><Section title="Manager Information"><Detail label="Full Name" value={manager.name} /><Detail label="Employee ID" value={manager.employeeId} /><Detail label="Role" value={manager.role} /><Detail label="Assigned Branch" value={manager.branch} /><Detail label="Status" value={manager.idStatus} /></Section></div><section className="min-w-0 border-t border-slate-100 pt-5 lg:mt-4 lg:border-l lg:border-t-0 lg:pl-5 lg:pt-0"><h4 className="text-xs font-bold uppercase tracking-wide text-slate-500">Manager ID Preview</h4><div className="mt-4 flex justify-center gap-5"><ManagerIdFace side="front" manager={manager} compact /><ManagerIdFace side="back" manager={manager} compact /></div></section></div></Modal>
}

function ManagerIdPreview({ generating = false, manager, onClose, onPrimary, primaryLabel }) {
  return <><div className="fixed inset-0 z-[90] flex items-center justify-center overflow-hidden bg-slate-950/45 sm:p-4 lg:pl-[226px] xl:pl-[266px]"><button type="button" className="absolute inset-0" onClick={onClose} aria-label="Close" /><section className="relative flex h-dvh max-h-dvh w-full max-w-3xl flex-col overflow-hidden bg-white shadow-2xl sm:h-auto sm:max-h-[calc(100dvh-2rem)] sm:rounded-xl"><header className="flex shrink-0 items-center justify-between border-b border-slate-100 px-4 py-3 sm:px-6 sm:py-4"><h2 className="text-lg font-bold text-slate-950 sm:text-xl">Manager ID Preview</h2><button type="button" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-lg text-slate-500 hover:bg-slate-100" aria-label="Close"><HiOutlineXMark className="h-5 w-5" /></button></header><div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-4 py-4 sm:px-6"><div className="grid justify-items-center gap-4 sm:grid-cols-2 sm:gap-8"><ManagerIdFace side="front" manager={manager} /><ManagerIdFace side="back" manager={manager} /></div>{!generating ? <section className="mt-5 border-t border-slate-100 pt-4"><h3 className="text-sm font-bold text-slate-900">Print Settings</h3><dl className="mt-3 grid gap-2 text-sm"><div className="flex justify-between gap-4"><dt className="text-slate-500">Size</dt><dd className="font-bold text-slate-900">2.125 × 3.37 in</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">Orientation</dt><dd className="font-bold text-slate-900">Portrait</dd></div><div className="flex justify-between gap-4"><dt className="text-slate-500">Scale</dt><dd className="font-bold text-slate-900">100% / Actual Size</dd></div></dl></section> : null}</div><footer className="flex shrink-0 justify-end gap-3 border-t border-slate-200 bg-white px-4 pb-[calc(0.75rem+env(safe-area-inset-bottom))] pt-3 sm:px-6 sm:py-4">{generating ? <Secondary onClick={onClose}>Back</Secondary> : null}<button type="button" onClick={onPrimary} className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-[#00675b] px-5 text-sm font-bold text-white hover:bg-[#005348]">{generating ? <HiOutlinePlus className="h-5 w-5" /> : <HiOutlinePrinter className="h-5 w-5" />}{primaryLabel}</button></footer></section></div>{!generating ? <ManagerIdPrintLayout manager={manager} /> : null}</>
}

function ManagerIdFace({ compact = false, manager, side }) {
  const sizeClass = compact ? "max-w-[145px]" : "max-w-[270px]"
  const branch = manager.branch.toLowerCase().includes("branch") ? manager.branch.toUpperCase() : `${manager.branch.toUpperCase()} BRANCH`
  const nameSize = manager.name.length > 28 ? 32 : manager.name.length > 20 ? 37 : 43
  if (side === "back") return <section className="w-full"><p className="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">Back</p><div className={`relative aspect-[2.125/3.37] w-full ${sizeClass} overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm`}><img src={managerIdBackArtwork} alt="Lyfe Pharmacy manager ID back" className="absolute inset-0 h-full w-full object-fill" /><svg viewBox="0 0 638 1013" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full" aria-label={`Assigned branch ${manager.branch}, employee ID ${manager.employeeId}`}><rect x="70" y="420" width="498" height="78" fill="#f1f3f2" /><foreignObject x="82" y="424" width="474" height="70"><div xmlns="http://www.w3.org/1999/xhtml" style={{ alignItems: "center", color: "#07553e", display: "flex", fontFamily: "Arial, sans-serif", fontSize: branch.length > 24 ? 29 : 37, fontWeight: 800, height: "100%", justifyContent: "center", lineHeight: 1.05, overflow: "hidden", textAlign: "center", textTransform: "uppercase" }}>{branch}</div></foreignObject><rect x="165" y="582" width="308" height="64" fill="#f1f3f2" /><text x="319" y="627" textAnchor="middle" fill="#07553e" fontSize="36" fontWeight="800" style={{ whiteSpace: "nowrap" }}>{manager.employeeId.replace("-", " - ")}</text></svg></div></section>
  return <section className="w-full"><p className="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">Front</p><div className={`relative aspect-[2.125/3.37] w-full ${sizeClass} overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm`}><img src={managerIdFrontArtwork} alt="Lyfe Pharmacy manager ID front" className="absolute inset-0 h-full w-full object-fill" /><svg viewBox="0 0 638 1013" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full" aria-label={`Manager ID for ${manager.name}`}><defs><clipPath id={`manager-photo-${manager.employeeId.replace(/[^a-zA-Z0-9]/g, "")}`}><circle cx="319" cy="421" r="174" /></clipPath></defs>{manager.photo ? <image href={manager.photo} x="145" y="247" width="348" height="348" preserveAspectRatio="xMidYMid slice" clipPath={`url(#manager-photo-${manager.employeeId.replace(/[^a-zA-Z0-9]/g, "")})`} /> : null}<rect x="92" y="638" width="454" height="95" fill="#f2f4f3" fillOpacity="0.98" /><foreignObject x="100" y="641" width="438" height="88"><div xmlns="http://www.w3.org/1999/xhtml" style={{ alignItems: "center", color: "#07553e", display: "flex", fontFamily: "Arial, sans-serif", fontSize: nameSize, fontWeight: 800, height: "100%", justifyContent: "center", lineHeight: 1.02, overflow: "hidden", textAlign: "center", textTransform: "uppercase" }}>{manager.name}</div></foreignObject><rect x="100" y="731" width="438" height="52" fill="#f2f4f3" fillOpacity="0.98" /><text x="319" y="769" textAnchor="middle" fill="#07553e" fontSize={manager.role.length > 18 ? 27 : 32} fontWeight="500">{manager.role.toUpperCase()}</text><rect x="165" y="790" width="308" height="48" fill="#f2f4f3" fillOpacity="0.98" /><text x="319" y="826" textAnchor="middle" fill="#07553e" fontSize="29" fontWeight="800" style={{ whiteSpace: "nowrap" }}>{manager.employeeId.replace("-", " - ")}</text><foreignObject x="160" y="838" width="318" height="64"><div xmlns="http://www.w3.org/1999/xhtml" style={{ background: "white", height: "100%", overflow: "hidden" }}><Barcode value={manager.barcode} /></div></foreignObject></svg></div></section>
}

function ManagerIdPrintLayout({ manager }) {
  if (typeof document === "undefined") return null
  return createPortal(<div className="manager-id-print-layout" aria-hidden="true"><style>{`@page { size: 2.125in 3.37in; margin: 0; } @media screen { .manager-id-print-layout { display: none; } } @media print { html, body { width: 2.125in !important; margin: 0 !important; padding: 0 !important; background: #fff !important; } body > *:not(.manager-id-print-layout) { display: none !important; } .manager-id-print-layout { display: block !important; width: 2.125in !important; margin: 0 !important; padding: 0 !important; } .manager-id-print { display: block !important; width: 2.125in !important; height: 3.37in !important; margin: 0 !important; padding: 0 !important; overflow: hidden !important; break-after: page; page-break-after: always; print-color-adjust: exact !important; -webkit-print-color-adjust: exact !important; } .manager-id-print:last-child { break-after: auto; page-break-after: auto; } .manager-id-print > section > p { display: none !important; } .manager-id-print > section > div { width: 2.125in !important; max-width: none !important; height: 3.37in !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; } }`}</style><div className="manager-id-print"><ManagerIdFace side="front" manager={manager} /></div><div className="manager-id-print"><ManagerIdFace side="back" manager={manager} /></div></div>, document.body)
}

function ConfirmDeactivateManager({ manager, onCancel, onConfirm }) { return <Modal title="Deactivate Manager ID" onClose={onCancel}><p className="text-sm leading-6 text-slate-600">Are you sure you want to deactivate the Manager ID for <strong className="text-slate-900">{manager.name}</strong>?</p><p className="mt-2 text-sm leading-6 text-slate-600">The ID will no longer be considered active. The employee account itself will not be deleted, archived, or deactivated.</p><div className="mt-6 flex justify-end gap-3"><Secondary onClick={onCancel}>Cancel</Secondary><button type="button" onClick={onConfirm} className="h-11 rounded-lg bg-red-600 px-5 text-sm font-bold text-white hover:bg-red-700">Deactivate ID</button></div></Modal> }

function SearchField({ noMargin = false, onChange, placeholder, value }) {
  return <label className={`relative block w-full max-w-[440px] ${noMargin ? "" : "mt-4"}`}><HiOutlineMagnifyingGlass className="pointer-events-none absolute left-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-slate-400" /><input type="search" value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className={`${inputClass} pl-11`} /></label>
}

function GenerateCard({ nextCardId, onClose, onPreview, reverifyMonths }) {
  const today = new Date()
  const issued = today.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })
  const issuedShort = today.toLocaleDateString("en-US", { month: "2-digit", day: "2-digit", year: "2-digit" })
  const reverify = calculateReverifyDate(today, reverifyMonths)
  const [form, setForm] = useState({ name: "", type: "PWD", address: "", birthDate: "", sex: "", idNumber: "", disability: "", issuedBy: "", governmentIdIssued: "", cardId: nextCardId, barcode: nextCardId, issued, issuedShort, reverifyBy: reverify.long, reverifyShort: reverify.short, status: "Active" })
  const age = calculateAge(form.birthDate)
  const canPreview = Boolean(form.name.trim() && form.address.trim() && form.birthDate && age !== null && form.sex && form.idNumber.trim() && (form.type !== "PWD" || form.disability.trim()))
  const update = (key, value) => setForm((current) => ({ ...current, [key]: value }))
  return <Modal title="Generate Discount Card" onClose={onClose} maxWidth="max-w-3xl"><form onSubmit={(event) => { event.preventDefault(); if (canPreview) onPreview({ ...form, name: form.name.trim(), address: form.address.trim(), age, governmentId: form.idNumber.trim() }) }}><h3 className="text-xs font-bold uppercase tracking-wide text-slate-500">Eligibility</h3><div className="mt-3 w-[220px] max-w-full"><Field label="Eligibility Type *"><select value={form.type} onChange={(event) => setForm((current) => ({ ...current, type: event.target.value, idNumber: "", disability: "" }))} className={inputClass}><option>PWD</option><option>Senior Citizen</option></select></Field></div><h3 className="mt-5 border-t border-slate-100 pt-5 text-xs font-bold uppercase tracking-wide text-slate-500">Cardholder Information</h3><div className="mt-3 grid gap-4 sm:grid-cols-2"><Field label="Full Name *"><input required value={form.name} onChange={(event) => update("name", event.target.value)} placeholder="Enter full name" className={inputClass} /></Field><Field label="Date of Birth *"><input required type="date" max={today.toISOString().slice(0, 10)} value={form.birthDate} onChange={(event) => update("birthDate", event.target.value)} className={inputClass} /></Field><div className="sm:col-span-2"><Field label="Address *"><input required value={form.address} onChange={(event) => update("address", event.target.value)} placeholder="Enter address" className={inputClass} /></Field></div><Field label="Sex *"><select required value={form.sex} onChange={(event) => update("sex", event.target.value)} className={inputClass}><option value="">Select sex</option><option>Female</option><option>Male</option></select></Field><Field label="Age"><input readOnly value={age ?? ""} placeholder="Auto calculated" className={`${inputClass} cursor-not-allowed bg-slate-50 text-slate-600`} /></Field></div><h3 className="mt-5 border-t border-slate-100 pt-5 text-xs font-bold uppercase tracking-wide text-slate-500">Government ID Information</h3><div className="mt-3 grid gap-4 sm:grid-cols-2"><Field label={`${form.type === "PWD" ? "PWD" : "Senior Citizen"} ID Number *`}><input required value={form.idNumber} onChange={(event) => update("idNumber", event.target.value)} placeholder={`Enter ${form.type === "PWD" ? "PWD" : "Senior Citizen"} ID`} className={inputClass} /></Field><Field label="Government ID Date Issued"><input type="date" max={today.toISOString().slice(0, 10)} value={form.governmentIdIssued} onChange={(event) => update("governmentIdIssued", event.target.value)} className={inputClass} /></Field>{form.type === "PWD" ? <Field label="Disability / Category *"><input required value={form.disability} onChange={(event) => update("disability", event.target.value)} placeholder="Enter disability/category" className={inputClass} /></Field> : null}<div className="sm:col-span-2"><Field label="Issued By / Municipality or Office"><input value={form.issuedBy} onChange={(event) => update("issuedBy", event.target.value)} placeholder="Enter issuing office" className={inputClass} /></Field></div></div><h3 className="mt-5 border-t border-slate-100 pt-5 text-xs font-bold uppercase tracking-wide text-slate-500">Lyfe Card Information</h3><div className="mt-3 grid gap-4 sm:grid-cols-3"><ReadOnly label="Card ID" value={form.cardId} help="Automatically generated" /><ReadOnly label="Lyfe Card Date Issued" value={form.issued} help="Automatically generated" /><ReadOnly label="Re-Verify By" value={form.reverifyBy} help="Automatically calculated" /></div><div className="mt-6 flex justify-end border-t border-slate-100 pt-4"><button type="submit" disabled={!canPreview} className="h-11 rounded-lg bg-[#00675b] px-6 text-sm font-bold text-white hover:bg-[#005348] disabled:cursor-not-allowed disabled:bg-slate-300">Preview Card</button></div></form></Modal>
}

function CardDetails({ card, onClose }) {
  return <Modal title="Discount Card Details" onClose={onClose} maxWidth="max-w-4xl">
    <div className="flex items-start justify-between gap-4 border-b border-slate-100 pb-4">
      <div><h3 className="text-xl font-bold text-slate-950">{card.cardId}</h3><p className="mt-1 font-bold text-slate-800">{card.name}</p><p className="mt-1 text-sm text-slate-500">{card.type}</p></div>
      <StatusBadge status={card.status} />
    </div>
    <div className="grid gap-6 lg:grid-cols-[minmax(0,58fr)_minmax(320px,42fr)] lg:gap-0">
      <div className="min-w-0 lg:pr-5">
        <Section title="Cardholder Information"><Detail label="Full Name" value={card.name} /><Detail label="Address" value={card.address || "—"} /><Detail label="Date of Birth" value={formatInputDate(card.birthDate)} /><Detail label="Age" value={card.age ?? "—"} /><Detail label="Sex" value={card.sex || "—"} /><Detail label="Eligibility" value={card.type} /></Section>
        <Section title="Government ID Information"><Detail label={card.type === "PWD" ? "PWD ID Number" : "Senior Citizen ID"} value={maskId(card.governmentId)} />{card.type === "PWD" ? <Detail label="Disability / Category" value={card.disability || "—"} /> : null}<Detail label="Issued By / Office" value={card.issuedBy || "—"} /><Detail label="Government ID Issued" value={formatInputDate(card.governmentIdIssued)} /></Section>
        <Section title="Lyfe Card Information"><Detail label="Card ID" value={card.cardId} /><Detail label="Lyfe Card Date Issued" value={card.issued} /><Detail label="Re-Verify By" value={card.reverifyBy} /></Section>
      </div>
      <section className="min-w-0 border-t border-slate-100 pt-5 lg:mt-4 lg:border-l lg:border-t-0 lg:pl-5 lg:pt-0">
        <h4 className="text-xs font-bold uppercase tracking-wide text-slate-500">Discount Card Preview</h4>
        <div className="mt-4 flex flex-col items-center gap-5" aria-label={`Discount card preview for ${card.name}`}>
          <figure className="w-full max-w-[360px]"><figcaption className="mb-2 text-center text-xs font-semibold text-slate-500">Front</figcaption><div className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm"><img src={cardFrontArtwork} alt="Lyfe Pharmacy discount card front" className="block h-auto w-full" /></div></figure>
          <figure className="w-full max-w-[360px]"><figcaption className="mb-2 text-center text-xs font-semibold text-slate-500">Back</figcaption><div className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm"><DynamicCardBack card={card} /></div></figure>
        </div>
      </section>
    </div>
  </Modal>
}

function CardPreview({ card, onBack, onPrimary, primaryLabel, printAfterPrimary = false }) {
  const handlePrimary = () => { onPrimary(); if (printAfterPrimary) window.setTimeout(() => window.print(), 0) }
  return <><Modal title="Card Preview" onClose={onBack} maxWidth="max-w-4xl"><div className="discount-card-screen grid gap-4 xl:grid-cols-2"><CardFace label="Front"><img src={cardFrontArtwork} alt="Lyfe Pharmacy discount card front" /></CardFace><CardFace label="Back"><DynamicCardBack card={card} /></CardFace></div><p className="mt-3 text-xs font-medium text-slate-500">Print size: 105 × 48 mm <span className="px-1 text-slate-300">•</span> Use 100% / Actual Size</p><div className="mt-4 flex justify-end border-t border-slate-100 pt-4"><Primary onClick={handlePrimary}><HiOutlinePrinter className="h-5 w-5" />{primaryLabel}</Primary></div></Modal><PrintCardLayout card={card} /></>
}

function PrintCardLayout({ card }) {
  if (typeof document === "undefined") return null
  return createPortal(<div className="discount-card-print" aria-hidden="true"><style>{`@page { size: 105mm 48mm; margin: 0; } @media screen { .discount-card-print { display: none; } } @media print { html, body { width: 105mm !important; margin: 0 !important; padding: 0 !important; background: #fff !important; } body > *:not(.discount-card-print) { display: none !important; } .discount-card-print { display: block !important; position: absolute !important; left: 0 !important; top: 0 !important; width: 105mm !important; margin: 0 !important; padding: 0 !important; } .discount-card-side { display: block !important; width: 105mm !important; height: 48mm !important; margin: 0 !important; padding: 0 !important; overflow: hidden !important; break-after: page; page-break-after: always; print-color-adjust: exact !important; -webkit-print-color-adjust: exact !important; } .discount-card-side:last-child { break-after: auto; page-break-after: auto; } .discount-card-side > div, .discount-card-side > img { width: 105mm !important; height: 48mm !important; } .discount-card-side img { width: 100% !important; height: 100% !important; object-fit: fill !important; display: block !important; } }`}</style><section className="discount-card-side"><img src={cardFrontArtwork} alt="" /></section><section className="discount-card-side"><DynamicCardBack card={card} /></section></div>, document.body)
}

function DynamicCardBack({ card }) {
  return <div className="relative overflow-hidden"><img src={cardBackArtwork} alt="Lyfe Pharmacy discount card back" className="block w-full" /><svg viewBox="0 0 1240 567" className="absolute inset-0 h-full w-full" aria-label={`Dynamic card information for ${card.cardId}`}><rect x="35" y="22" width="410" height="410" fill="#f7faf7" /><text x="43" y="60" fill="#08735d" fontSize="34" fontWeight="700">CARD ID</text><text x="43" y="126" fill="#005b49" fontSize="61" fontWeight="800">{card.cardId}</text><line x1="43" y1="161" x2="438" y2="161" stroke="#178b70" strokeWidth="4" /><foreignObject x="44" y="203" width="393" height="204"><div xmlns="http://www.w3.org/1999/xhtml" style={{ height: "100%", padding: "12px 38px 8px", border: "3px solid #d7d7d7", borderRadius: "28px", background: "white" }}><Barcode value={card.barcode} /><div style={{ textAlign: "center", fontSize: "27px", lineHeight: 1 }}>{card.barcode}</div></div></foreignObject><rect x="495" y="122" width="180" height="84" fill="#f7faf7" /><text x="585" y="155" textAnchor="middle" fill="#08735d" fontSize="27" fontWeight="700">DATE ISSUED</text><text x="585" y="197" textAnchor="middle" fill="#111827" fontSize="26">{card.issuedShort}</text><rect x="495" y="326" width="180" height="92" fill="#f7faf7" /><text x="585" y="361" textAnchor="middle" fill="#08735d" fontSize="25" fontWeight="700">RE-VERIFY BY</text><text x="585" y="405" textAnchor="middle" fill="#111827" fontSize="26">{card.reverifyShort}</text></svg></div>
}

function Barcode({ value }) {
  const code39 = { "0":"nnwwnwnnw", "1":"wnnwnnnnw", "2":"nnwwnnnnw", "3":"wnwwnnnnn", "4":"nnnwwnnnw", "5":"wnnwwnnnn", "6":"nnwwwnnnn", "7":"nnnwnnwnw", "8":"wnnwnnwnn", "9":"nnwwnnwnn", A:"wnnnnwnnw", B:"nnwnnwnnw", C:"wnwnnwnnn", D:"nnnnwwnnw", E:"wnnnwwnnn", F:"nnwnwwnnn", G:"nnnnnwwnw", H:"wnnnnwwnn", I:"nnwnnwwnn", J:"nnnnwwwnn", K:"wnnnnnnww", L:"nnwnnnnww", M:"wnwnnnnwn", N:"nnnnwnnww", O:"wnnnwnnwn", P:"nnwnwnnwn", Q:"nnnnnnwww", R:"wnnnnnwwn", S:"nnwnnnwwn", T:"nnnnwnwwn", U:"wwnnnnnnw", V:"nwwnnnnnw", W:"wwwnnnnnn", X:"nwnnwnnnw", Y:"wwnnwnnnn", Z:"nwwnwnnnn", "-":"nwnnnnwnw", "*":"nwnnwnwnn" }
  const bars = Array.from(`*${value.toUpperCase()}*`).flatMap((character, charIndex) => Array.from(code39[character] ?? code39["-"], (width, index) => ({ wide: width === "w", bar: index % 2 === 0, key: `${charIndex}-${index}` })))
  let x = 0
  return <svg viewBox="0 0 260 74" className="h-auto w-full bg-white" role="img" aria-label={`Barcode ${value}`}>{bars.map((item) => { const width = item.wide ? 3 : 1.4; const currentX = x; x += width + .8; return item.bar ? <rect key={item.key} x={currentX} y="4" width={width} height="62" fill="#000" /> : null })}</svg>
}

function ConfirmDeactivate({ card, onCancel, onConfirm }) {
  return <Modal title="Deactivate Discount Card" onClose={onCancel}><p className="text-sm leading-6 text-slate-600">Are you sure you want to deactivate <strong className="text-slate-900">{card.cardId}</strong> for {card.name}?</p><p className="mt-2 text-sm leading-6 text-slate-600">This card will no longer be valid for discount transactions. Its record will be retained for history and audit purposes.</p><div className="mt-6 flex justify-end gap-3"><Secondary onClick={onCancel}>Cancel</Secondary><button type="button" onClick={onConfirm} className="h-11 rounded-lg bg-red-600 px-5 text-sm font-bold text-white hover:bg-red-700">Deactivate Card</button></div></Modal>
}
function ConfirmBulkDeactivate({ count, onCancel, onConfirm }) { return <Modal title="Deactivate Discount Cards" onClose={onCancel}><p className="text-sm leading-6 text-slate-600">Are you sure you want to deactivate {count} discount cards?</p><p className="mt-2 text-sm leading-6 text-slate-600">These cards will no longer be valid for discount transactions. Their records will remain available for history and audit purposes.</p><div className="mt-6 flex justify-end gap-3"><Secondary onClick={onCancel}>Cancel</Secondary><button type="button" onClick={onConfirm} className="h-11 rounded-lg bg-red-600 px-5 text-sm font-bold text-white hover:bg-red-700">Deactivate Cards</button></div></Modal> }

function ReverifyCardModal({ card, months, onCancel, onConfirm }) { const [form, setForm] = useState({ address: card.address || "", birthDate: card.birthDate || "", sex: card.sex || "", governmentId: card.governmentId || "", disability: card.disability || "", issuedBy: card.issuedBy || "", governmentIdIssued: card.governmentIdIssued || "" }); const update = (key, value) => setForm((current) => ({ ...current, [key]: value })); const canSave = Boolean(form.address.trim() && form.birthDate && form.sex && form.governmentId.trim() && (card.type !== "PWD" || form.disability.trim())); return <Modal title="Re-verify Discount Card" onClose={onCancel} maxWidth="max-w-3xl"><p className="mb-4 text-sm text-slate-600">Review and confirm continued eligibility for <strong>{card.name}</strong> ({card.cardId}).</p><div className="grid gap-4 sm:grid-cols-2"><Field label="Address *"><input required value={form.address} onChange={(event) => update("address", event.target.value)} className={inputClass} /></Field><Field label="Date of Birth *"><input required type="date" value={form.birthDate} onChange={(event) => update("birthDate", event.target.value)} className={inputClass} /></Field><Field label="Sex *"><select value={form.sex} onChange={(event) => update("sex", event.target.value)} className={inputClass}><option value="">Select sex</option><option>Female</option><option>Male</option></select></Field><Field label={`${card.type} ID Number *`}><input required value={form.governmentId} onChange={(event) => update("governmentId", event.target.value)} className={inputClass} /></Field>{card.type === "PWD" ? <Field label="Disability / Category *"><input required value={form.disability} onChange={(event) => update("disability", event.target.value)} className={inputClass} /></Field> : null}<Field label="Issued By / Office"><input value={form.issuedBy} onChange={(event) => update("issuedBy", event.target.value)} className={inputClass} /></Field><Field label="Government ID Issued"><input type="date" value={form.governmentIdIssued} onChange={(event) => update("governmentIdIssued", event.target.value)} className={inputClass} /></Field></div><div className="mt-6 flex justify-end gap-3"><Secondary onClick={onCancel}>Cancel</Secondary><button type="button" disabled={!canSave} onClick={() => onConfirm({ ...form, age: calculateAge(form.birthDate), ...getReverificationUpdate(months) })} className="h-11 rounded-lg bg-[#00675b] px-5 text-sm font-bold text-white hover:bg-[#005348] disabled:cursor-not-allowed disabled:bg-slate-300">Complete Re-verification</button></div></Modal> }

function Modal({ children, maxWidth = "max-w-xl", onClose, title }) { return <div className="fixed inset-0 z-[90] flex items-center justify-center overflow-y-auto bg-slate-950/45 p-3 sm:p-4 lg:pl-[226px] xl:pl-[266px]"><button type="button" className="absolute inset-0" onClick={onClose} aria-label="Close" /><section className={`relative max-h-[calc(100dvh-1.5rem)] w-full ${maxWidth} overflow-y-auto rounded-xl bg-white p-4 shadow-2xl sm:max-h-[calc(100dvh-2rem)] sm:p-6`}><button type="button" onClick={onClose} className="absolute right-3 top-3 grid h-9 w-9 place-items-center rounded-lg text-slate-500 hover:bg-slate-100 sm:right-4 sm:top-4" aria-label="Close"><HiOutlineXMark className="h-5 w-5" /></button><h2 className="pr-10 text-lg font-bold text-slate-950 sm:text-xl">{title}</h2><div className="mt-4 sm:mt-5">{children}</div></section></div> }
function Section({ children, title }) { return <section className="mt-4"><h4 className="text-xs font-bold uppercase tracking-wide text-slate-500">{title}</h4><div className="mt-2 divide-y divide-slate-100">{children}</div></section> }
function Detail({ label, value }) { return <div className="grid grid-cols-[145px_minmax(0,1fr)] gap-4 py-2.5 text-sm"><span className="font-medium text-slate-500">{label}</span><span className="font-bold text-slate-900">{value}</span></div> }
function PolicyValue({ label, primary = false, value }) { return <div className="min-w-0 lg:px-5 first:lg:pl-0 last:lg:pr-0"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">{label}</p><p className={`mt-1.5 font-bold leading-5 text-slate-900 ${primary ? "text-xl lg:text-sm" : "text-sm"}`}>{value}</p></div> }
function Field({ children, label }) { return <label className="block"><span className="mb-2 block text-sm font-bold text-slate-700">{label}</span>{children}</label> }
function ReadOnly({ help, label, value }) { return <Field label={label}><input readOnly value={value} className={`${inputClass} cursor-not-allowed bg-slate-50 text-slate-600`} /><span className="mt-1 block text-xs text-slate-400">{help}</span></Field> }
function ReadOnlyValue({ label, value }) { return <div><p className="text-xs font-bold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-1 text-sm font-bold text-slate-900">{value}</p></div> }
function Primary({ children, onClick }) { return <button type="button" onClick={onClick} className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-[#00675b] px-5 text-sm font-bold text-white hover:bg-[#005348]">{children}</button> }
function Secondary({ children, onClick }) { return <button type="button" onClick={onClick} className="h-11 rounded-lg border border-slate-200 px-5 text-sm font-bold text-slate-700 hover:bg-slate-50">{children}</button> }
function StatusBadge({ status }) { const tone = status === "Active" ? "bg-emerald-100 text-emerald-700" : status === "Re-verification Due" ? "bg-amber-100 text-amber-700" : "bg-slate-200 text-slate-600"; return <span className={`inline-flex whitespace-nowrap rounded-md px-2.5 py-1 text-xs font-bold ${tone}`}>{status}</span> }
function ViewButton({ label, onClick }) { return <button type="button" onClick={onClick} className="mx-auto grid h-9 w-9 place-items-center rounded-lg border border-slate-200 text-[#0b6b51] hover:bg-emerald-50" aria-label={label} title={label}><HiOutlineEye className="h-5 w-5" /></button> }
function PageButton({ active, children, disabled, onClick }) { return <button type="button" disabled={disabled} onClick={onClick} className={`grid h-9 min-w-9 place-items-center rounded-lg border px-2 text-sm font-bold ${active ? "border-[#00675b] bg-[#00675b] text-white" : "border-slate-200 bg-white text-slate-600"} disabled:cursor-not-allowed disabled:text-slate-300`}>{children}</button> }
function EmptyRow({ colSpan, detail, title }) { return <tr><td colSpan={colSpan} className="px-4 py-10 text-center"><p className="text-sm font-bold text-slate-600">{title}</p>{detail ? <p className="mt-1 text-xs font-medium text-slate-400">{detail}</p> : null}</td></tr> }
function CardFace({ children, label }) { return <section><p className="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">{label}</p><div className="overflow-hidden rounded-lg border border-slate-200 bg-white">{children}</div></section> }
function maskId(value) { if (!value) return "—"; return `${"•".repeat(Math.max(4, value.length - 4))}${value.slice(-4)}` }
function calculateAge(value) { if (!value) return null; const birthDate = new Date(`${value}T00:00:00`); if (Number.isNaN(birthDate.getTime()) || birthDate > new Date()) return null; const today = new Date(); let age = today.getFullYear() - birthDate.getFullYear(); if (today.getMonth() < birthDate.getMonth() || (today.getMonth() === birthDate.getMonth() && today.getDate() < birthDate.getDate())) age -= 1; return age }
function formatInputDate(value) { if (!value) return "—"; const date = new Date(`${value}T00:00:00`); return Number.isNaN(date.getTime()) ? "—" : date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) }
function calculateReverifyDate(issuedDate, months) { const interval = Number(months) || 24; const date = new Date(issuedDate); date.setMonth(date.getMonth() + interval); return { long: date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }), short: date.toLocaleDateString("en-US", { month: "2-digit", day: "2-digit", year: "2-digit" }) } }
function getReverificationUpdate(months) { const today = new Date(); const next = calculateReverifyDate(today, months); return { status: "Active", reverifyBy: next.long, reverifyShort: next.short } }
function resolveCardStatus(card) { if (card.status === "Inactive") return card.status; const deadline = new Date(card.reverifyBy); return !Number.isNaN(deadline.getTime()) && deadline < new Date() ? "Re-verification Due" : card.status }
function getPaginationItems(currentPage, pageCount) { if (pageCount <= 5) return Array.from({ length: pageCount }, (_, index) => index + 1); if (currentPage <= 3) return [1, 2, 3, "ellipsis", pageCount]; if (currentPage >= pageCount - 2) return [1, "ellipsis", pageCount - 2, pageCount - 1, pageCount]; return [1, "ellipsis", currentPage, "ellipsis", pageCount] }

export default SuperAdminDiscounts
